@Controller("gps_tracks")
@UseGuards(JwtAuthGuard)
export class FleetGpsTrackController {
  constructor(private readonly prisma: PrismaService) {}

  @Patch(":id/status")
  async updateStatus(
    @Param("id") id: string,
    @CurrentUser() user: UserEntity,
    @Body() dto: UpdateStatusDto
  ) {
    const count = await this.prisma.fleet_gps_track.count({
      where: { id: id, driver_id: user.id }
    });
    if (count === 0) {
      throw new ForbiddenException("Unauthorized to modify this fleet_gps_track");
    }
    return this.prisma.fleet_gps_track.update({
      where: { id: id },
      data: { status: dto.status }
    });
  }
}

