@Controller("kyc_records")
@UseGuards(JwtAuthGuard)
export class IdentityKycController {
  constructor(private readonly prisma: PrismaService) {}

  @Patch(":id/status")
  async updateStatus(
    @Param("id") id: string,
    @CurrentUser() user: UserEntity,
    @Body() dto: UpdateStatusDto
  ) {
    const count = await this.prisma.identity_kyc.count({
      where: { id: id, applicant_id: user.id }
    });
    if (count === 0) {
      throw new ForbiddenException("Unauthorized to modify this identity_kyc");
    }
    return this.prisma.identity_kyc.update({
      where: { id: id },
      data: { status: dto.status }
    });
  }
}

