  @Patch(":id/status")
  async updateStatus(
    @Param("id") id: string,
    @CurrentUser() user: UserEntity,
    @Body() dto: UpdateStatusDto
  ) {
    const count = await this.prisma.clinical_trial.count({
      where: { id: id, participant_id: user.id }
    });
    if (count === 0) {
      throw new ForbiddenException("Unauthorized to modify this clinical_trial");
