      where: { id: id, employee_id: user.id }
    });
    if (count === 0) {
      throw new ForbiddenException("Unauthorized to modify this employee_file");
    }
    return this.prisma.employee_file.update({
      where: { id: id },
      data: { status: dto.status }
    });
  }
}

